def solve(lengths, page, layers, heads, width, latent, rope, dtype_bytes, ranks):
    dims = (page, layers, heads, width, latent, dtype_bytes, ranks)
    if any(type(n) is not int or n < 1 for n in dims) or type(rope) is not int or rope < 0 or heads % ranks:
        raise ValueError("invalid dimensions")
    if any(type(n) is not int or n < 0 for n in lengths):
        raise ValueError("invalid sequence length")
    slots = sum((n + page - 1) // page * page for n in lengths)
    factor = slots * layers * dtype_bytes
    return factor * 2 * (heads // ranks) * width, factor * (latent + rope)
